// Pokémon Champions on the battle engine: @pkmn/sim does not ship Pokémon Showdown's champions mods, so they are registered here
// (engine/src/champions/, generated by scripts/build_champions.mjs from Pokémon Showdown, MIT) with their formats: Champions OU and
// UU, the Battle Stadium Singles and VGC regulations M-A and M-B, and the custom games. Its rules: stat points instead of EVs (HP =
// base + points + 75, the rest base + points + 20, then the nature; at most 32 in one stat, 66 in all), no move above 20 PP, Mega
// Evolution, Champions' own item and move changes. Imported once by core.mjs, so the engine, the app and the playable page all
// know these formats.
import {Dex} from '@pkmn/sim';
import {Formats, MODS} from './champions/index.mjs';
import {championsPoints} from './points.mjs';

export const CHAMPIONS_MODS = Object.keys(MODS);

function compat(scripts) {
  // the mods are written for Pokémon Showdown 0.11, whose move loop calls a recoil helper @pkmn/sim 0.10 does not have yet: the
  // same recoil as the engine's own loop
  const actions = scripts.actions || (scripts.actions = {});
  if (!actions.applyRecoilDamage) {
    actions.applyRecoilDamage = function applyRecoilDamage(damageDealt, move, pokemon) {
      if (move.recoil || move.id === 'chloroblast') {
        const before = pokemon.hp;
        this.battle.damage(this.calcRecoilDamage(damageDealt, move, pokemon), pokemon, pokemon, 'recoil');
        if (pokemon.hp <= pokemon.maxhp / 2 && before > pokemon.maxhp / 2) this.battle.runEvent('EmergencyExit', pokemon, pokemon);
      }
      if (move.struggleRecoil) {
        const before = pokemon.hp;
        const recoil = this.battle.clampIntRange(Math.round(pokemon.baseMaxhp / 4), 1);
        this.battle.directDamage(recoil, pokemon, pokemon, {id: 'strugglerecoil'});
        if (pokemon.hp <= pokemon.maxhp / 2 && before > pokemon.maxhp / 2) this.battle.runEvent('EmergencyExit', pokemon, pokemon);
      }
    };
  }
  return scripts;
}

let done = false;
export function registerChampions() {
  if (done) return;
  done = true;
  for (const [mod, data] of Object.entries(MODS)) Dex.mod(mod, {...data, Scripts: compat({...data.Scripts})});
  // @pkmn/sim's formats.extend() builds the list and then drops it: add the formats to the lists the base dex and each mod keep
  // (a format can be another's rule, "[Gen 9 Champions] OU" in UU, and rules are looked up in the format's own dex)
  const id = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '');
  for (const dex of [Dex, ...CHAMPIONS_MODS.map((m) => Dex.mod(m))]) {
    const formats = dex.formats.load();
    const known = new Set(formats.all().map((f) => f.id));
    const fresh = Formats.filter((f) => !known.has(id(f.name))).map((f) => ({...f, ruleset: f.ruleset ? f.ruleset.slice() : f.ruleset,
      banlist: f.banlist ? f.banlist.slice() : f.banlist}));
    const list = formats.buildList(fresh);
    formats.formatsListCache.push(...list);
  }
}

/** Whether a format plays by Champions' rules (its stat points are the EVs field, 0-32). */
export function isChampions(formatId) {
  const f = Dex.formats.get(formatId, true);
  return CHAMPIONS_MODS.includes(f.mod);
}

/** The sets of a team for a Champions format, whose EVs field holds the stat points themselves (0-32, 66 in all). Silver keeps
 * points as EVs (points.mjs: 32 points = 252 EVs) and teams come with classic EVs too, so a spread is turned into points unless it
 * already reads as points (none above 32 and 66 at most in all, as a Champions export has them). */
export function championsSets(sets) {
  return sets.map((s) => ({...s, evs: championsPoints(s.evs || {})}));
}

registerChampions();
